import { STATISTICS, STATS_GRAPH, EVENTS_PROPERTY_LIST } from 'types'
import { message } from 'antd'
import _, { omit } from 'underscore'
import Router from 'next/router'
import commonApi from 'services/commonApi'
import { errorMessageGlobal } from 'Utils/constants/index'
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder'
import { loadSelectedEventCount } from 'Utils/helpers/loadSelectedEventCount'
import { currentTimeZone, getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils'
import { postErrorHandle, getApiCalledTime } from './common'
import {
  trackPageViews,
} from './trackingReport'

export const statistics = (data, type) => ({
    type: type || STATISTICS,
    data
  })
export const loader = flag => (dispatch, getState) => {
  const statisticsData = { ...getState().statisticsReducer }
  statisticsData.loader = flag
  dispatch(statistics(statisticsData))
}
export const statsDropdownOptions = payload => (dispatch, getState) => {
  const statisticsData = { ...getState().statisticsReducer }
  return commonApi
    .forwardApi(payload, 'events/plotting_options')
    .then(async res => {
      const data = await res.data
      if (res.status === 200) {
        statisticsData.dropdownData = data
        dispatch(statistics(statisticsData, 'DEFAULT_STATS_LIST'))
        return res.data
      }
      return res
    })
    .catch(error => 
      // if (error) getErrorHandle(dispatch, statistics, error)
       error
    )
}
export const eventsGraph = (payload) => async (dispatch, getState) => {
  const statisticsData = _.clone(getState().statisticsReducer)
  const { event } = getState().appFilter
  const { selectedEventName } = getState().eventTable
  const { table: eventNameList } = getState().eventTable
  dispatch(loader(true))
  delete statisticsData.graphData
  await dispatch(statistics(statisticsData, STATS_GRAPH))
  if(getState().urlReducer.parentType === 'statistics') {
    const segment = [ ...getState().appFilter.event.segment ]
    let url = `${process.env.REDIRECT_URL}/app/${getState().urlReducer.appId}/events/analytics?`
    const query = `/integration?parentType=statistics&appId=${getState().urlReducer.appId}`
    url = urlSegmentEncoder(url, segment)
    Router.push(query, url)
  }
  const dateSegment = { ...getState().appFilter.dateSegment }
  // payload.filters = [...getState().appFilter.event.segment, ...dateSegment ]
  payload.filters = event.segment
  payload.date_range = {
    ...dateSegment,
    timezoneOffset: getTimezoneOffset(dateSegment?.tz, new Date() )
  }
  // const selectedEventName = [...getState().eventTable.selectedEvent]
  // const eventNameList = [...getState().eventTable.table]
  payload.filters = selectedEventName?.length
    ? loadSelectedEventCount(selectedEventName, eventNameList, [...getState().appFilter.event.segment]) ||
      payload.filters
    : payload.filters
  dispatch(getApiCalledTime(Math.floor(Date.now() / 1000)))
  // * CX-2255 -add timezone offset to groupByList 
  payload.group_list = payload.group_list.map(item => {
      return {
                ...item,
                time_zone_offset: getTimezoneOffset(dateSegment.tz, new Date())
            }
    })

  if(payload?.filters?.length > 0 && payload?.filters?.some(filter => filter?.attribute === 'nce_name')) {
    return null
  }
  
  return commonApi
    .pythonWithCancelApi(payload, 'events/build_event_graph')
    .then(async res => {
      dispatch(getApiCalledTime())
      const data = await res.data
        if (res.status === 200) {
          // track event
          dispatch( trackPageViews( null, {
            eventName: 'wa_display_event_analytics',
            track_type: 'event',
            eventProperty: {},
          } ) )

          if (data.success) {
            statisticsData.graphData = data
          } else {
            statisticsData.graphData = 'Graph could not be created'
          }
          dispatch(statistics(statisticsData, 'STATS_GRAPH'))
          // dispatch(loader(false))
        } else {
          statisticsData.graphData = 'Graph could not be created'
          dispatch(statistics(statisticsData, 'STATS_GRAPH'))
          // dispatch(loader(false))
        }
        dispatch(loader(false))
      return data
    })
    .catch(error => {
      if(error && !error.toString().includes('Cancel') ){
        dispatch(getApiCalledTime())
        dispatch(loader(false))
        statisticsData.graphData = errorMessageGlobal
        dispatch(statistics(statisticsData, 'STATS_GRAPH'))
      }
      // if (error && error.response)
      //   postErrorHandle(dispatch, statistics, error.response)
      return error.response
    })
}
export const anyKeyData = data => (dispatch, getState) => {
  const statisticsData = { ...getState().statisticsReducer }
  statisticsData[data.fgName] = data.flag
  dispatch(statistics(statisticsData))
}
export const getPropertyList = payload => (dispatch, getState) => {
  dispatch(anyKeyData({ fgName: 'loaderForPL', flag: true }))
  const statisticsData = { ...getState().statisticsReducer }
  return commonApi
    .forwardApi(payload, 'events')
    .then(async res => {
      const data = await res.data.data
      if (res.status === 200) {
        if (res.data.success) {
          statisticsData.propertyList = data
          dispatch(statistics(statisticsData, EVENTS_PROPERTY_LIST))
          dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
        }
        return res.data
      }
        data.error
          ? message.error('Request to get data failed' || data.error.message)
          : 'Oops! Something Bad Happened!'
        dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))

      return res
    })
    .catch(error => {
      if (error && error.response) postErrorHandle(dispatch, statistics, error.response)
      dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
      return error
    })
}
export const handleValuesByName = payload => (dispatch, getState) => {
  const statisticsData = JSON.parse(JSON.stringify(getState().statisticsReducer))
  statisticsData[payload.dropName] = payload.data
  dispatch(statistics(statisticsData))
  return payload.data
}
export const amendValues = payload => (dispatch, getState) => {
  const statisticsData = JSON.parse(JSON.stringify(getState().statisticsReducer))
  statisticsData[payload.key] = payload.data
  dispatch(statistics(statisticsData))
}
export const clearEventStatsData = () => (dispatch, getState) => {
  let statisticsData = JSON.parse(JSON.stringify(getState().statisticsReducer))
    statisticsData = omit(statisticsData, 'loader', 'propertyList', 'payloadStatistics', 'graphData')
    statisticsData.grpByVal = [
      {
        table: 'event',
        attribute: 'event_period_day',
        tooltip: 'Day on which event was recorded.',
        period: 86400,
        display: 'Day',
        time_zone_offset: currentTimeZone,
      },
      {
        display: 'event name',
        type: 'str',
        tooltip: 'Assigned name of event.',
        table: 'event',
        attribute: 'event_name',
      },
    ]
    statisticsData.eventDropValues = {
      attribute: 'event_count',
      type: 'count',
      table: 'event',
      operator: '',
      display: 'events'
    }
    statisticsData.graphSelectedVal = {}
    dispatch(statistics(statisticsData))
}
