import axios from 'axios'
import {axiosInstance} from './globalInstance'

const {CancelToken} = axios
let cancel = null
let request = 0
const searchAttributeApiUrl = `${process.env.PYTHON_API_URL}/search_attribute`
class FilterApi {

  static async fetchRemoteData (data, appId, filter) {
    request++
    if (cancel) {
      await cancel(request)
    }
    const response = await axiosInstance.post(`${process.env.API_URL  }/app/${appId}/${filter}/search-attribute`, data,
      {withCredentials: true,
        cancelToken: new CancelToken((c) => {
            // An executor function receives a cancel function as a parameter
          cancel = c
          request = 0
        })})
    cancel = null
    return response
  }

  static async searchAttrApi (data, appId, filter) {
    const response = await axiosInstance.post(`${process.env.API_URL  }/app/${appId}/${filter}/search-attribute`, data,
    {withCredentials: true})
    return response
  }

  static async applyFilter (appId, type, data) {
    const response = await axiosInstance.post(`${process.env.API_URL  }/app/${appId}/${type}/custom-list`, data, {withCredentials: true})
    return response
  }

  static async fetchScreenRemoteData (data, appId, filter) {
    const response = await axiosInstance.post(
      `${process.env.API_URL}/app/${appId}/${filter}/search-attribute`,
      data,
      { withCredentials: true }
    );
    return response
  }

  static async getEventPropertyList (appId) {
    const response = await axiosInstance({
      method: 'GET',
      url: `${process.env.PYTHON_API_URL}/preference/${appId}/get-event-property-list`,
      withCredentials: true,
    });
    return response
  }

  static async getPropertiesWithCancelToken (data) {
    request++
    if (cancel) await cancel(request)
    const response = await axiosInstance.post(searchAttributeApiUrl, data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          cancel = c
          request = 0
        })
      })
    cancel = null
    return response
  }

  static async getPropertiesWithoutCancelToken (data) {
    const response = await axiosInstance.post(searchAttributeApiUrl, data, { withCredentials: true })
    return response
  }
}

export default FilterApi
