
import commonApi from 'services/commonApi'
import { errorMessageGlobal } from 'Utils/constants/index'
import { omit } from 'lodash'
import {
  SESSION_STATISTICS,
  SESSION_STATISTICS_GRAPH,
  SESSION_STATISTICS_DLIST,
  SESSION_STATISTICS_BOXES,
  SESSION_STATISTICS_BOXES_UNIQ_TOP
} from 'types'

import { currentTimeZone } from 'Utils/DateConversion/dateConversionUtils'
import { updateSelectedEvent } from './event'
import { getApiCalledTime } from './common'

export const statistics = (data, type = SESSION_STATISTICS) => ({
  type,
  data,
})
export const anyKeyData = data => (dispatch, getState) => {
  const statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData[data.fgName] = data.flag
  dispatch(statistics(statisticsData))
}
export const statsDropdownOptions = (payload) => (dispatch) => commonApi
    .forwardApi(payload, `sessions/plotting_options`)
    .then(async res => {
      const data = await res.data
      if (res.status === 200) {
        dispatch(statistics(data, SESSION_STATISTICS_DLIST))
        return res.data
      }
      return res
    })
    .catch(error => error
    )
export const loadGraph = (payload) => async (dispatch, getState) => {
  dispatch(anyKeyData({ fgName: 'graphLoader', flag: true }))
  const statisticsData = { ...getState().sessionStatisticsReducer }
  delete statisticsData.graphData
  await dispatch(statistics(statisticsData, SESSION_STATISTICS_GRAPH))
  dispatch(getApiCalledTime(Math.floor(Date.now() / 1000)))
  return commonApi
    .pythonWithCancelApi(payload, `sessions/build_session_graph`)
    .then(async res => {
      dispatch(getApiCalledTime())
      const data = await res.data
      dispatch(anyKeyData({ fgName: 'graphLoader', flag: false }))
      if (res.status === 200) {
        if (data.success) statisticsData.graphData = data
        else statisticsData.graphData = 'Following selection did not give a meaningful result'
      } else statisticsData.graphData = errorMessageGlobal
      dispatch(statistics(statisticsData, SESSION_STATISTICS_GRAPH))
      return res.data
    })
    .catch(error => {
      dispatch(anyKeyData({ fgName: 'graphLoader', flag: false }))
      if(error && !error.toString().includes('Cancel')) {
        dispatch(getApiCalledTime())
        statisticsData.graphData = errorMessageGlobal
        dispatch(statistics(statisticsData, 'SESSION_STATISTICS_GRAPH'))
      }
      return error
    })
}
export const loader = flag => (dispatch, getState) => {
  const statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData.loader = flag
  dispatch(statistics(statisticsData))
}
export const getStatsBoxes = (payload) => async (dispatch, getState) => {
  dispatch(anyKeyData({ fgName: 'loaderForPL', flag: true }))
  const statisticsData = { ...getState().sessionStatisticsReducer }
  delete statisticsData.statsBoxes
  await dispatch(statistics(statisticsData, SESSION_STATISTICS_BOXES))
  return commonApi
    .forwardApi(payload, `sessions/stat_box_data`)
    .then(async res => {
      const data = await res.data
      statisticsData.statsBoxes = data
      dispatch(statistics(statisticsData, SESSION_STATISTICS_BOXES))
      dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
      return data
    })
    .catch(error => {
      statisticsData.statsBoxes = error.response
      dispatch(statistics(statisticsData, SESSION_STATISTICS_BOXES))
      dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
      return error
    })
}
export const getUniqueUserBox = (payload) => async (dispatch, getState) => {
  dispatch(anyKeyData({ fgName: 'loaderForPL', flag: true }))
  const statisticsData = { ...getState().sessionStatisticsReducer }
  delete statisticsData.uniqueUserBox
  await dispatch(statistics(statisticsData, SESSION_STATISTICS_BOXES_UNIQ_TOP))
  return commonApi
    .forwardApi(payload, `sessions/total_user_count`)
    .then(async res => {
      const data = await res.data.Total
      if (res.status === 200) {
        statisticsData.uniqueUserBox = data
        dispatch(statistics(statisticsData, SESSION_STATISTICS_BOXES_UNIQ_TOP))
      }
      dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
      return data
    })
    .catch(error => {
      dispatch(anyKeyData({ fgName: 'loaderForPL', flag: false }))
      return error
    })
}
export const handleValuesByName = (payload) => (dispatch, getState) => {
  const statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData[payload.dropName] = payload.data
  dispatch(statistics(statisticsData))
}
export const amendValues = payload => (dispatch, getState) => {
  const statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData[payload.key] = payload.data
  dispatch(statistics(statisticsData))
}
export const clearStatsData = () => (dispatch, getState) => {
  let statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData = omit(statisticsData, 'loader', 'propertyList', 'payloadStatistics', 'graphData')
  statisticsData.group_list = [
    {
      table: 'session',
      attribute: 'session_period_day',
      tooltip: 'Day on which session was recorded.',
      period: 86400,
      display: 'Day',
      time_zone_offset: currentTimeZone,
    },
  ]
  statisticsData.aggregation_list = {
    attribute: 'session_count',
    type: 'count',
    table: 'session',
    operator: ''
  }
  statisticsData.series_plot_options = {}
  statisticsData.selectedBox = {
    attrOfSmallBox: 'count',
        mainKey: 'Sessions',
        tooltip:'Total number of recorded app launches during Feb 19 - Feb 26, 2020 (7 days).',
        graph_info: 'Recorded session number',
        actionIndex: 1
  }
  dispatch(updateSelectedEvent([]))
  dispatch(statistics(statisticsData))
}

export const setActiveTab = key => (dispatch, getState) => {
  const statisticsData = { ...getState().sessionStatisticsReducer }
  statisticsData.selectedTab = key
  dispatch(statistics(statisticsData))
}
