import _ from 'underscore'
import {EVENT_NAME} from 'types'
import EventApi from 'services/eventApi'
import {getErrorHandle} from './common'

export const gotEventName = data => ({
    type: EVENT_NAME,
    data
  })

export const getEventName = (data) => async (dispatch, getState) => {
  const eventTable = {...getState().eventTable}
  const tableData = {...getState().tableReducer}
  tableData.loader = true
  eventTable.table = []
  eventTable.eventTableLoader = true
  await dispatch(gotEventName(eventTable))
  return EventApi.getEventTable(data, data.appid)
        .then(res => {
          eventTable.table = res.data
          eventTable.manuallyChanged = false
          eventTable.eventTableLoader = false
          dispatch(gotEventName(eventTable))
        })
        .catch(error => getErrorHandle(dispatch, null, error))
}

export const updateSelectedEvent = (selectedEvent, manuallyChangedReset) => (dispatch, getState) => {
  const eventTable = {...getState().eventTable}
  eventTable.manuallyChanged = typeof manuallyChangedReset === 'boolean' ? manuallyChangedReset : true
  eventTable.selectedEvent = selectedEvent || []
   dispatch(gotEventName(eventTable))
}

export const eventNameFilter = (selectedRowKeys, eventTable, operator) => {
  const filterData = {operator: 'in', value: []}
  if (selectedRowKeys.length && selectedRowKeys.length !== eventTable.length) {
    const unSelectedEvent = eventTable.filter((x) => {
      const eventIndex = _.indexOf(selectedRowKeys, x.eventname)
      if (eventIndex < 0) {
        return x
      }
    })
    if (operator) {
        if (operator === 'notin') {
          filterData.value = unSelectedEvent.map((x) => x.eventname)
          filterData.operator = operator
        } else {
          filterData.value = selectedRowKeys
          filterData.operator = operator
        }
    } else if (selectedRowKeys.length > unSelectedEvent.length) {
        if (unSelectedEvent.length === 0) {
          filterData.value = selectedRowKeys
          filterData.operator = 'in'
        } else {
          filterData.value = unSelectedEvent.map((x) => x.eventname)
          filterData.operator = 'notin'
        }
      } else if (selectedRowKeys.length < unSelectedEvent.length) {
        filterData.value = selectedRowKeys
        filterData.operator = 'in'
      } else if (
        selectedRowKeys.length &&
        selectedRowKeys.length === unSelectedEvent.length
      ) {
        filterData.value = selectedRowKeys
        filterData.operator = 'in'
      }
  }
  return filterData
}
export const valueByKeyEvent = (key, value) => (dispatch, getState) => {
  const event = JSON.parse(JSON.stringify(getState().eventTable))
  event[key] = value
  return dispatch(gotEventName(event))
}
