/* eslint-disable no-shadow */
export type DateRangeAttribute = 'device_time' | 'upload_time';

export enum ACTIVITY_FILTER_CATEGORY {
    SESSION = 'SESSION',
    SCREENVISIT = 'SCREENVISIT',
    SMART_EVENT = 'SMART_EVENT',
    CODED_EVENT = 'CODED_EVENT',
} 
export type ActivityDateRangeType =  {
    attribute: DateRangeAttribute,
    operator: string,  //* 'between'
    value: {
      lower: Date,
      upper: Date
    },
    tz: string,
    labelId: string
    table?: string
  }
export type ActivityConfigType = {
    // attribute:'user_with_session_activity',
    operator:string,
    value: number,
} 
export type ActivityPropertyType = {
    attribute: string;
    operator:  string;
    value?:     string[] | string | undefined;
    table:     string;
    open?:      boolean; // * only for redux 
    property?: any;
    property_name?: string;
    has_sequence?: any;
    isLocal?: boolean;
}

export type ActivityFilterPayloadType = {
    attribute:                     string;
    operator:                      string;
    value:                         number;
    activity_attribute_date_range: ActivityDateRangeType;
    filters:                       ActivityPropertyType[];
    active?:                       boolean;
}

export interface TActivityFilterJSON {
    attribute:     string;
    title:         string;
    alternativeTitle?:         string;
    type:          string;
    isSearchable:  boolean;
    info:          string;
    table?:         string;
    features?:     string[];
    webInfo?:      string;
    valueMapping?: string[];
    hidden?:       boolean;
    filterTitle?:  string;
    filterTable?:  string;
    default?:      {
        attribute: string;
        operator:  string;
        value:     string[];
        table:     string;
    }[];
}

export type ActivityFilterConfigurationType = {
    defaultValue: ActivityFilterPayloadType,
    defaultValueWithFilters?: ActivityFilterPayloadType,
    configuration: {
        label: string,
        properties: TActivityFilterJSON[]
        allSupportedProperties?: Record<string, TActivityFilterJSON[]>
        type: ACTIVITY_FILTER_CATEGORY
    }
}