export const activityFilterSelector:Record<string, ActivityFilterConfigurationType > = {
    user_with_session_activity: {
        defaultValue: defaultSessionActivityFilterSegment,
        defaultValueWithFilters:defaultSessionActivityFilterSegment,
        configuration: {
            label: "session",
            properties: flattenObjectValues(categorizedSessionActivity),
            allSupportedProperties:{
                "All properties": flattenObjectValues(categorizedSessionActivity),
                ...categorizedSessionActivity
            },
            type: ACTIVITY_FILTER_CATEGORY.SESSION
        }
    },
    user_with_event_activity: { 
        defaultValue: defaultCodedEventActivityFilterSegment,
        defaultValueWithFilters: {
            ...defaultCodedEventActivityFilterSegment,
            filters: [
                {
                    attribute: 'event_name',
                    operator: 'in',
                    table: 'event',
                    open: true,
                    isLocal: true,
                }
            ],
            active: true,
        },
        configuration: {
            label: "coded event",
            properties: flattenObjectValues(categorizedCodedEventActivity),
            allSupportedProperties:{
                    "All properties": flattenObjectValues(categorizedCodedEventActivity),
                    ...categorizedCodedEventActivity,
            },
            type: ACTIVITY_FILTER_CATEGORY.CODED_EVENT
        }
    },
    user_with_smart_event_activity: { 
        defaultValue: defaultSmartEventActivityFilterSegment,
        defaultValueWithFilters: {
            ...defaultSmartEventActivityFilterSegment,
            filters: [
                {
                    attribute: 'nce_name',
                    operator: 'in',
                    table: 'no_code_event',
                    open: true,
                    isLocal: true,
                }
            ],
            active: true,
        },
        configuration: {
            label: "smart event",
            properties: flattenObjectValues(categorizedSmartEventActivity),
            allSupportedProperties:{
                    "All properties": flattenObjectValues(categorizedSmartEventActivity),
                    ...categorizedSmartEventActivity,
            },
            type: ACTIVITY_FILTER_CATEGORY.SMART_EVENT
        }
    },
    user_with_screenvisit_activity: {
        defaultValue: defaultScreenVisitActivityFilterSegment,
        defaultValueWithFilters:{
            ...defaultScreenVisitActivityFilterSegment,
            filters: [
                {
                    attribute: 'screen_name',
                    operator: 'in',
                    table: 'screenvisit',
                    open: true,
                    isLocal: true,
                }
            ],
            active: true,
        },
        configuration: {
            label: "screen visit",
            properties: flattenObjectValues(categorizedScreenVisitActivity),
            allSupportedProperties:{
                    "All properties": flattenObjectValues(categorizedScreenVisitActivity),
                    ...categorizedScreenVisitActivity,
            },
            type: ACTIVITY_FILTER_CATEGORY.SCREENVISIT
        }
    }
}
export const defaultActivityFilterSegment = defaultSessionActivityFilterSegment;
