export const getActivityPropertiesListByAttribute = (attribute:string):TActivityFilterJSON[] => {
    if(attribute && activityFilterSelector[attribute]?.configuration?.properties) {
        return activityFilterSelector[attribute].configuration.properties;
    }
    return [];
}
export const getActivityFilterAttributeByType = (type:ACTIVITY_FILTER_CATEGORY):string=> {
    return Object.keys(activityFilterSelector).find((key)=> activityFilterSelector[key].configuration.type === type) || '';
}