// * CX-1876 : THIS FUNCTION CHECKS IF THE ACTIVITY FILTER IS CHANGED FROM DEFAULT STATE
export const hasActivityFilterChangedFromDefaultState = (activityFilterSegments: any) => {
    if (activityFilterSegments?.length > 1) return true;
    if (activityFilterSegments?.length === 1) {
        // * we need to check if the default value is changed or not
        const hasSegment = activityFilterSegments?.some((filter: any) => filter?.filters?.length);
        const hasConfigChanged = JSON.stringify({
            operator: activityFilterSegments[0]?.operator,
            value: activityFilterSegments[0]?.value,
            dateRangeOperator: activityFilterSegments[0]?.activity_attribute_date_range.operator,
            dateRangeAttribute: activityFilterSegments[0]?.activity_attribute_date_range.attribute,
            tz: activityFilterSegments[0]?.activity_attribute_date_range.tz
        }) !== JSON.stringify({
            operator: defaultActivityFilterSegment.operator,
            value: defaultActivityFilterSegment.value,
            dateRangeOperator: defaultActivityFilterSegment.activity_attribute_date_range.operator,
            dateRangeAttribute: defaultActivityFilterSegment.activity_attribute_date_range.attribute,
            tz: defaultActivityFilterSegment.activity_attribute_date_range.tz
        });
        const hasDateRangeChanged = !isEqual(activityFilterSegments[0]?.activity_attribute_date_range.labelId, defaultActivityFilterSegment.activity_attribute_date_range.labelId);
        return hasSegment || hasConfigChanged || hasDateRangeChanged;
    }
    return false
}


/**
 * Extends the provided filters with user session activity filters if applicable.
 *
 * @param activityFilterList - Segments containing activity-related filter details.
 * @param filters - Existing filters to be extended.
 * @param isUserV2 - Indicates whether the user version is V2, determining applicability.
 * @returns The extended list of filters including user session activity filters for V2 users, or the original filters if not applicable.
 */
export const getFilterListWithActivityFilterCheck = (
    activityFilterList: ActivityFilterPayloadType[],
    normalFilters: any,
    isUserV2: boolean
) => {
    if (!isUserV2) return normalFilters;
    const userSessionActivityList = activityFilterList?.map(
        ({ filters, operator, value , activity_attribute_date_range, attribute }) => ({
            attribute,
            operator,
            value,
            filters:  map(filters, (i) => omit(i, ['open', 'isLocal'])),
            activity_attribute_date_range: {
                attribute: activity_attribute_date_range.attribute,
                operator: activity_attribute_date_range.operator,
                value: activity_attribute_date_range.value,
                tz: activity_attribute_date_range.tz,
                labelId: activity_attribute_date_range?.labelId || ''
            },
        })
    );

    return [...normalFilters, ...userSessionActivityList];
};



export function isValidActivityFilterSegment(activityFilterList: typeof defaultActivityFilterSegment[]) {
    const isValidConfigCheck = (operator:string, value:number , dateRange: any) => {
        return !!operator && !!dateRange && Number(value) >= 0
    }
    // Check if all config values are valid
    const baseValidation = activityFilterList?.every(activityFilter =>
        isValidConfigCheck(activityFilter.operator, activityFilter.value , activityFilter.activity_attribute_date_range)
    );

    if (!baseValidation) return false;

    // If any segment has length, check that all segment values are valid
    if (activityFilterList?.some(filter => filter.filters.length)) {
      return activityFilterList.every(filter =>
            filter?.filters?.every((i) => 
             i?.property ? (Boolean(i.property.name) && Boolean(i.property.value)) : Boolean(i.value)
            )
        );
    }

    return true;
}


export function activityDateRangeUrlEncode(activity_attribute_date_range: typeof defaultActivityFilterSegment['activity_attribute_date_range']) {
    const { operator, attribute, labelId, tz, value } = activity_attribute_date_range;
    return {
        o: operator,
        a: attribute,
        lb: labelId,
        tz,
        v: value
    }
}

export function activityDateRangeUrlDecode(activity_attribute_date_range: any) {
    const { o, a, lb, tz, v, tb } = activity_attribute_date_range;
    const decoded = {
        operator: o,
        attribute: a,
        labelId: lb,
        tz,
        value: v,
        table: tb
    }
    !o && delete decoded.operator;
    !a && delete decoded.attribute;
    !lb && delete decoded.labelId;
    !tz && delete decoded.tz;
    !v && delete decoded.value;
    !tb && delete decoded.table;
    return decoded;
}


export function activityFilterUrlEncode(filters: any) {
    const { attribute, operator, value, labelId, tz, table, eventName,property_name ,propertyType, property, isLocal} = filters;
    const isAppFilter = ['user_custom_property', 'event_custom_property', 'utm', 'session_screen_with_property', 'session_screen_with_property_list'].indexOf(attribute) > -1; 
    if(isAppFilter){
        return {
            a: attribute,
            o: operator,
            pn: property_name,
            pv: value,
            tb: table,
        }
    }
    const encoded = {
        a: attribute,
        o: operator,
        v: value,
        lb: labelId,
        tz,
        tb: table,
        p: property,
        isLo: isLocal,
    }
    !attribute && delete encoded.a;
    !operator && delete encoded.o;
    !value && delete encoded.v;
    !labelId && delete encoded.lb;
    !tz && delete encoded.tz;
    !table && delete encoded.tb;
    !isLocal && delete encoded.isLo;
    return encoded
}
export function aggregateByAttributeAndEncode(data:ActivityFilterPayloadType[]) {
    const params = new URLSearchParams();
    const encodedActivityFilters:Record<string, unknown> = data.reduce( (acc: Record<string, unknown[]>, obj) => {
      const attr = obj.attribute || '';
      if (!acc[attr]) {
        acc[attr] = [];
      }
      
      const { filters: activityFilterList, activity_attribute_date_range, operator, value, attribute } = obj;
      const encodedDateRange = activityFilterUrlEncode(activity_attribute_date_range);
      const encodedActivityProperty = activityFilterList.map((j) => activityFilterUrlEncode(j));
      
      acc[attr].push({ 
        filters: encodedActivityProperty, 
        activity_attribute_date_range: encodedDateRange, 
        o: operator, 
        v: value, 
        a: attribute 
      });
      
      return acc;
    }, {});
    Object.keys(encodedActivityFilters).forEach((key) => {
        params.append(key, JSON.stringify(encodedActivityFilters[key]));
   });
    return params;
}

export function activityFilterUrlDecode(activityFilter: any) {
    const { a, o, v, lb, tz, tb, tzo , en, pn, pt, pv , p, isLo} = activityFilter;
    const isAppFilter = ['user_custom_property', 'event_custom_property', 'utm', 'session_screen_with_property', 'session_screen_with_property_list','user_first_utm','screen_utm'].indexOf(a) > -1; 
    const checkForPN = ( propertyName:string ) => {
        if(propertyName){
            return isArray(propertyName) ? propertyName[0] : propertyName
        }
        return ''
    }
    if(isAppFilter){
        return {
            attribute: a,
            operator: o,
            value: pv || v,
            table: tb,
            property_name: checkForPN(pn),
        }
    }
    const decoded = {
        attribute: a,
        operator: o,
        value: v,
        labelId: lb,
        tz: tz || currentTimeZone,
        table: tb,
        timezoneOffset: tzo,
        property: p,
        isLocal: isLo,
    }

    !a && delete decoded.attribute;
    !o && delete decoded.operator;
    !v && delete decoded.value;
    !lb && delete decoded.labelId;
    !tb && delete decoded.table;
    !tzo && delete decoded.timezoneOffset;
    !p && delete decoded.property;
    !tz && delete decoded.tz;
    !isLo && delete decoded.isLocal;

    // TODO:Can be removed if equal and not_equal removed from CD * To Support redirection from CD
    if (!["True","False"].includes(decoded.value)) {
        // * renaming not_equal--> not_in and equal--> in ; not supported in front-end Operator.json need to rename , both need array
        if (o === 'equal') {
            decoded.operator = 'in';
        }
        if (o === 'not_equal') {
            decoded.operator = 'not_in';
        }
        if (o === 'not_equal' || o === 'equal') {
            decoded.value = isArray(v) ? v : [v]; // * requires array for in and not_in
        }
    }
    if (a === 'session_recorded_hour_of_user' ){
         // * if its value is like ["4am","5 pm"] convert to ["4AM","5PM"]
            decoded.value = isArray(v) && (v as string[])?.map(time =>
                time.replace(/(\d+)\s*(AM|PM)/i, (_, hour, period) => `${hour}${period.toUpperCase()}`)
            );
    }
    if (a === 'session_recorded_weekday'){
        // * if not array convert to array
        decoded.value = isArray(v) ? v : [v.toLowerCase()];
        }
    return decoded;
}
export const decodeActivityFilterUrl = (url:string)=>async(dispatch:any, getState:any)=> {
    try {
        const regex = /([a-zA-Z0-9_]+)=([^&]+)/g;
        let match;
        let extractedData:ActivityFilterPayloadType[] = [];
        const normalFilters = getState().appFilter.user.segment

        // eslint-disable-next-line no-cond-assign
        while ((match = regex.exec(url)) !== null) {
            const key = match[1];
            const value = match[2];

            if (ActivityFilterAttributesList.includes(key)) { 
                try {
                    const parsedData = JSON.parse(decodeURIComponent(value));
                    if (Array.isArray(parsedData)) {
                        const decoded = parsedData.map((item) => ({
                            attribute: key,
                            operator: item?.o,
                            value: item?.v,
                            activity_attribute_date_range: activityFilterUrlDecode(item?.activity_attribute_date_range),
                            filters: item?.filters?.map((i:ActivityFilterPayloadType['filters']) => activityFilterUrlDecode(i)) || [],
                        } as ActivityFilterPayloadType));
                        extractedData = extractedData.concat(decoded);
                    }
                } catch (parseError:unknown) {
                    rollbar.error(parseError as string, `Error parsing JSON for ${key}`);
                }
            }
        }

        if (extractedData.length > 0) {
            dispatch(setActivityFilterSegment(extractedData, 'user'));
        } else if( !normalFilters.length ){
            //* case: (no any filter) add default activityFilter
            dispatch(setActivityFilterSegment([defaultActivityFilterSegment], 'user'));
        }
    } catch (e:unknown) {
        rollbar.error(e as string, 'Error processing user activity parameters from URL');
    }

}

/**
 * Returns the appropriate date range operator based on the provided date preset label ID.
 *
 * @param id - The date preset label ID.
 * 
 * Operators Configuration:
 * - 'absolute_today', 'absolute_yesterday' --> returns an empty string.
 * - undefined --> returns 'between'.
 * - Others --> returns 'in'.
 *
 * @returns The date range operator as a string.
 */
export const getActivityDateRangeOperator = (id: string) => {
    switch (id) {
        case 'absolute_today':
        case 'absolute_yesterday':
            return '';
        case undefined: 
        case '':
            return 'between';
        default:
            return 'in';
    }
}

export const hasActivityFilter = (filters: any) => {
    return filters.some((filter: any) => ActivityFilterAttributesList.includes(filter?.attribute || ''));
}

//* CX-2219: ActivityFilter Instrumentations
export const triggerActivityFilterSendEvent = (activityFilterSegment: ActivityFilterPayloadType) => {
    const { filters, operator, value, activity_attribute_date_range ,attribute} = activityFilterSegment;
    const removeValuesFromActivityFilters = {
            attribute,
            operator,
            value,
            number_of_filters: filters.length,
            filters: removeValuesFromFilters(filters),
            activity_attribute_date_range
        }
    return (dispatch: any) => {
        dispatch(trackPageViews(null, {
            eventName: 'wa_create_activity_filter',
            track_type: 'event',
            eventProperty: removeValuesFromActivityFilters,
            pageName: 'usersList',
        }));
    };
};

