// * update only activity config
export const updateActivityFilterConfig = (data, filterIndex ) =>(dispatch,getState) => {
    const {activityFilterList} = getState().appFilter.user;
    const findIndex = activityFilterList.findIndex((val, idx) => idx === filterIndex);

    // * if new data
    if (findIndex === -1) {
      const dataToStore = {
        ...activityFilterList,
        data
      }
      dispatch(setActivityFilterSegment(dataToStore, "user"));
      return
    } 

    // * update particular index data and update
    const updatedSegment = activityFilterList.map((val, idx) =>
        idx === filterIndex ? {
                ...data,
                filters: activityFilterList[filterIndex].filters, 
            } : val
        );
        dispatch(setActivityFilterSegment(updatedSegment, "user"));
         // * trigger send-event
    hasActivityFilterChangedFromDefaultState([updatedSegment[filterIndex]]) &&
    isValidActivityFilterSegment([updatedSegment[filterIndex]]) &&
    dispatch(triggerActivityFilterSendEvent(updatedSegment[filterIndex])); 
}
// * CX-2094: Event and Screen visit Activity Filter - Adjust operator and event value based on the event name filter before it
function adjustOperatorsAndValues(filterSegmentList) {
    // * Note: This function is used to adjust the operator and value of the event property filter based on recent the event name filter before it
    const lastFilterMap = {
        event_name: { operator: 'in', value: null},
        screen_name: { operator: 'in', value: null},
    };
    const updatedList = [];

    // eslint-disable-next-line no-plusplus
    for (let i = 0; i < filterSegmentList.length; i++) {
        const filterItem = clone(filterSegmentList[i]); 
       
        if (!['event_name','screen_name'].includes(filterItem.attribute)
         || (filterItem.attribute === 'screen_name' && !filterItem?.isLocal)
         || (filterItem.attribute === 'event_name' && !filterItem?.isLocal)
        ) {
            updatedList.push(filterItem);
            // eslint-disable-next-line no-continue
            continue;
        }

        if (!filterItem.property) {
            lastFilterMap[filterItem.attribute].operator = filterItem.operator;
            lastFilterMap[filterItem.attribute].value = filterItem.value;
        } else {
            filterItem.operator = lastFilterMap[filterItem.attribute].operator;
            filterItem.value =   lastFilterMap[filterItem.attribute].value;
        }

        updatedList.push(filterItem);
    }

    return updatedList;
}

// * CX-1876 either appends new property or updates current segment
export const updateActivityFilterSegment = (updatedSegment, filterIndex , active=false) =>(dispatch,getState) => {
    const {activityFilterList} = getState().appFilter.user;
    const findIndex = activityFilterList.findIndex((val, idx) => idx === filterIndex);

    // * if new property
    if (findIndex > -1) {
        const modifiedSegment = activityFilterList.map((val, idx) =>
            idx === filterIndex ? {
                ...activityFilterList[filterIndex],
                filters: adjustOperatorsAndValues(updatedSegment), 
                active // * set active for the most recent property
            } : {
                ...val,
                active:false // * remove all active flag 
            }
        );
        dispatch(setActivityFilterSegment(modifiedSegment, "user"));   
        // * trigger send-event
        hasActivityFilterChangedFromDefaultState([modifiedSegment[filterIndex]]) &&
        isValidActivityFilterSegment([modifiedSegment[filterIndex]]) &&
        dispatch(triggerActivityFilterSendEvent(modifiedSegment[filterIndex])); 
    }
}

// * add activity filter segment
export const appendActivityFilterSegment = (passedActivityFilter, openAddPropertyDropdown) =>
  (dispatch, getState) => {
    let timeout; 
    timeout && clearTimeout(timeout);
    const {activityFilterList} = getState().appFilter.user;
    const modifiedSegment = passedActivityFilter 
    const updatedSegment = [...activityFilterList, modifiedSegment]
    dispatch(setActivityFilterSegment(updatedSegment, "user"));
    if(openAddPropertyDropdown){
      timeout = setTimeout(() => {
           window.dispatchEvent(new CustomEvent(getAddPropertyDropdownConfig().eventId, { detail: { id: getAddPropertyDropdownConfig(modifiedSegment.attribute, updatedSegment.length-1).dropdownId} }));
        }, 0);
    }
    // * trigger send-event
    dispatch(triggerActivityFilterSendEvent(modifiedSegment)); 
}

export const resetActivityFilterSegment = () => (dispatch) => {
    dispatch(setActivityFilterSegment([activityFilterSelector.user_with_session_activity.defaultValue], "user"));
    // * trigger send-event
    dispatch(triggerActivityFilterSendEvent(activityFilterSelector.user_with_session_activity.defaultValue)); 
}
export const setFilterPageTable = (table) => ({ type: SET_PAGE_FILTER_TABLE, table })
const decodeFilterValue = (value) => {
  if (typeof value === 'string') {
    try { return decodeURIComponent(value) } catch { return value }
  }
  if (Array.isArray(value)) return value.map(decodeFilterValue)
  return value
}

export const decodeUrlV2 = (urlLink, isWebApp) => async (dispatch, getState) => {
  const result = []
  const { url, parentType } = getState().urlReducer;
  const urlNew = urlLink || url

  try {
     if (!['shortUrl', 'plan-downgrade', 'integration'].includes(parentType) && isValidURL(urlNew)) {
    urlNew?.replace(/([^?=&]+)=([^&]+)/g, (_, attribute, queryParams) => {
      if(attribute === 'screenname' || attribute === 'steps' || Object.keys(activityFilterSelector).includes(attribute)) return
      let values = queryParams
      values = isWebApp ? values.replace(/%3F/g, '?') : values.replace('%3F','')
      const newValues = decodeURIComponent(values)

      // check if the value is a valid JSON object
      let newValuesParsed
      try {
        newValuesParsed = JSON.parse(newValues)
        if ( typeof newValuesParsed !== 'object' && attribute !== 'isSessionEventTab' ) {
          return
        }
      } catch (error) {
        return
      }
      
      if (
        ['apikey',
          'appid',
          'eventproperty',
          'userproperty',
          'user_custom_property',
          'event_custom_property',
          'utm',
          'user_first_utm',
          'session_screen_with_property',
          'session_screen_with_property_list',
          'dateRange',
          'isSessionEventTab', 'date_range', 'upload_time', 'device_time'].indexOf(attribute) === -1
      ) {
        const value = decodeFilterValue(newValuesParsed.v)
        const operator = newValuesParsed.o
        const table = newValuesParsed.tb
        const hasSequence = newValuesParsed.has_sequence
        const filters = newValuesParsed?.filters
        const property = newValuesParsed.p;
        const timezoneOffset = newValuesParsed?.tzo
        const hasMassValue = newValuesParsed.hm
        const massValueSegmentId = newValuesParsed.mvs
        const massValuesId = newValuesParsed.mvi
        if (newValuesParsed) {
          const filterData = {
            attribute,
            operator,
            value,
            table,
            has_sequence: hasSequence,
            filters,
            property,
          }
          timezoneOffset && (filterData.timezoneOffset = timezoneOffset)
          hasMassValue && (filterData.has_mass_value = hasMassValue)
          massValueSegmentId && (filterData.mass_value_segment_id = massValueSegmentId)
          massValuesId && (filterData.mass_values_id = massValuesId)
          result.push({ ...filterData })
        }
      } else if (['eventproperty', 'userproperty', 'user_custom_property', 'event_custom_property' , 'utm', 'user_first_utm', 'session_screen_with_property', 'session_screen_with_property_list' ].indexOf(attribute) > -1) {
        if (newValuesParsed) {
          const filterData = ['eventproperty', 'userproperty'].indexOf(attribute) > -1 ?
          {
            attribute,
            eventName: newValuesParsed.en !== 'undefined' && newValuesParsed.en,
            propertyName: newValuesParsed.pn,
            operator: newValuesParsed.o,
            propertyValue: decodeFilterValue(newValuesParsed.pv),
          } : {
            attribute,
            event_name: newValuesParsed.en !== 'undefined' && newValuesParsed.en,
            property_name: newValuesParsed.pn || newValuesParsed.property_name,
            operator: newValuesParsed.o,
            value: decodeFilterValue(newValuesParsed.pv || newValuesParsed.v),
            table: newValuesParsed.tb
          }
          result.push({ ...filterData })
        }
      } else if (attribute === 'date_range') {
        const filterData = {
          attribute: 'upload_time',
          operator: 'between_dates',
          value: newValuesParsed.lower ? { lower: newValuesParsed.lower, upper: newValuesParsed.upper } : newValuesParsed.v,
          labelId: newValuesParsed.lb,
          tz: newValuesParsed.tz || currentTimeZone,
        }
        dispatch(getDateSegment(filterData))
      } 
      else if (attribute === 'upload_time' || attribute === 'device_time') { 
        const filterData = {
          attribute,
          operator: "between_dates",
          value: newValuesParsed.lower ? { lower: newValuesParsed.lower, upper: newValuesParsed.upper } : newValuesParsed.v,
          labelId: newValuesParsed.lb,
          tz: newValuesParsed.tz || currentTimeZone,
        }
        dispatch(getDateSegment(filterData))
      }else if (attribute === 'isSessionEventTab') dispatch(valueByKeyEvent(attribute, newValues))
    })
  }
  } catch (error) {
    rollbar.error(error, 'Error with url parse')
  }
  return result
}

export const callSessionStatisticsAPI = () => (dispatch, getState) => {
  const seriesPlotOptions = omit(getState().sessionStatisticsReducer.series_plot_options, 'display', 'key', 'img')
  const segment = [...getState().appFilter.session.segment]
  const appid = getState().currentAppReducer['_id']
  const dateSegment = { ...getState().appFilter.dateSegment }
  const filters = [ ...segment, ...[ dateSegment ] ]
  const { parentType } = getState().urlReducer
  const dynamicPayload = { appid, filters: [...segment], date_range: dateSegment }
  
  // Map for different parent types and their corresponding URLs
  const urlMap = {
    sessionStatistics: {
      analyticsUrl: `/app/${appid}/sessions/analytics?`,
      integrationUrl: `/integration?parentType=sessionStatistics&appId=${appid}`
    },
    aiSessionStatistics: {
      analyticsUrl: `/app/${appid}/aisessions/analytics?`,
      integrationUrl: `/integration?parentType=aiSessionStatistics&appId=${appid}`
    }
  }
  
  if(parentType === 'sessionStatistics' || parentType === 'aiSessionStatistics') {
    const urlConfig = urlMap[parentType]
    let url = urlConfig.analyticsUrl
    url = urlSegmentEncoder(url, filters)
    Router.push(urlConfig.integrationUrl, url)

  const listGrpBy = getState().sessionStatisticsReducer.group_list ? [...getState().sessionStatisticsReducer.group_list] : []
  const sessionAttrIndex = listGrpBy.map(v => v.attribute).indexOf('session_period')
  if(sessionAttrIndex > -1) listGrpBy[sessionAttrIndex].attribute = 'session_period_day'
  listGrpBy[0]['time_zone_offset'] = getTimezoneOffset(dateSegment.tz, new Date() )
  dispatch(loadGraph({
    appid,
    aggregation_list: [getState().sessionStatisticsReducer.aggregation_list],
    group_list: listGrpBy,
    filters: [...segment],
    date_range: {
      ...dateSegment,
      timezoneOffset: getTimezoneOffset(dateSegment.tz, new Date() )
    },
    series_plot_options: seriesPlotOptions,
  }))
  }

  if ( parentType !== "aiSessionsList" && parentType !== 'aiSessionStatistics' ) {
    dispatch(getStatsBoxes(dynamicPayload))
    dispatch(getUniqueUserBox(dynamicPayload))
  }
}

export const callEventsListAndGraphApi = () => async (dispatch, getState) => {
  const appid = getState().currentAppReducer['_id'];
  const {
    eventDropValues: aggregationList,
    grpByVal: groupList,
    graphSelectedVal,
  } = getState().statisticsReducer;

  const { appFilter } = getState();
  const clonedEventSegment = [ ...appFilter.event.segment ];
  const dateSegment = { ...appFilter.dateSegment };

  groupList[0]['time_zone_offset'] = getTimezoneOffset(dateSegment.tz, new Date() )

  const payload = {
    appid,
    aggregation_list: [aggregationList],
    group_list: groupList,
    filters: [],
    series_plot_options: omit(graphSelectedVal, 'display', 'key', 'img'),
  };

  const eventPropertyFilter = clonedEventSegment?.filter(
    (segment) => segment.attribute !== 'eventname'
  );
  const eventPropsReqBody = {
    attribute: 'event_custom_property',
    filter: clonedEventSegment?.length ? eventPropertyFilter : [],
    search: '',
    dropdownLimit: 501,
    date_range: dateSegment,
  };

  const userPropsReqBody = {
    attribute: 'user_custom_property',
    filter: [],
    search: '',
    dropdownLimit: 501,
    date_range: dateSegment,
  };

  const callEventProperties = async () => {
    dispatch(changeCommonValue('eventProperty_Ldr', true));
    await dispatch(
      getFilterPropertyRemoteData(
        eventPropsReqBody,
        'event-filter',
        'eventproperty'
      )
    ).then(() => dispatch(changeCommonValue('eventProperty_Ldr', false)));
  };

  const callUserProperties = async () => {
    dispatch(changeCommonValue('userProperty_Ldr', true));
    await dispatch(
      getFilterPropertyRemoteData(
        userPropsReqBody,
        'user-filter',
        'userproperty'
      )
    ).then(() => dispatch(changeCommonValue('userProperty_Ldr', false)));
  };
  dispatch(eventsGraph(payload));
  dispatch(
    getEventName(
      {
        appid,
        date_range: appFilter.dateSegment,
        filters: [],
      }
    )
  );
  await callEventProperties();
  callUserProperties();
};

export const applyScreenFlowFilter = (screenFlowImage) => (dispatch, getState) => {
  const appid = getState().currentAppReducer['_id'];
  const { screenDetailReducer: { screenFlowPayloadData }, appFilter  } = getState();
  const { dateSegment } = appFilter;

  const payload = {
    ...screenFlowPayloadData,
    appid,
    date_range: dateSegment
  };
  dispatch(getScreenFlow(payload, { type: 'screenFlowPlotGraph' }, null, screenFlowImage));
  dispatch(getScreenBurst(payload, { type: 'sunburstPlotGraph' }, null, screenFlowImage));
  dispatch(screenFlowPayload(payload));
  dispatch(flagSetForScreenFlow(false));
};
