/* eslint-disable no-plusplus */

export const urlSegmentEncoder = (url, segment = []) => {
  const segmentCopy = segment ? [...segment] : [];
  let urlCopy = url;
  let object;
  for (let i = 0; i < segmentCopy.length; i++) {
    const includesQueries = Boolean(segment.length)
    const includeQMark = i === 0 && !url.includes('?') && includesQueries ? '?' : ''
    const sign = i > 0 ? '&' : includeQMark
    const attribute = segmentCopy[i].attribute ? segmentCopy[i].attribute.toString() : ''
    const equalTo = '='
    if (!['eventproperty', 'userproperty', 'user_custom_property', 'event_custom_property' , 'utm', 'session_screen_with_property', 'session_screen_with_property_list', 'user_first_utm'].includes(segmentCopy[i].attribute)) {
      object = segmentCopy[i].property
        ? JSON.stringify({
            o: segmentCopy[i].operator,
            v: segmentCopy[i].value,
            p: segmentCopy[i].property,
            t: segmentCopy[i].type,
            tb: segmentCopy[i].table,
            tzo: segmentCopy[i]?.timezoneOffset,
          })
        : JSON.stringify({
            o: segmentCopy[i].operator,
            v: segmentCopy[i].value,
            t: segmentCopy[i].type,
            tb: segmentCopy[i].table,
            has_sequence: segmentCopy[i].has_sequence,
            lb: segmentCopy[i].labelId,
            tz: segmentCopy[i].tz,
            filters: segmentCopy[i].filters,
            tzo: segmentCopy[i]?.timezoneOffset,
            hm: segmentCopy[i].has_mass_value,
            mvs: segmentCopy[i].mass_value_segment_id,
            mvi: segmentCopy[i].mass_values_id,
          })
      object = encodeURIComponent(object)
    } else {
      const isAppFilter = ['user_custom_property', 'event_custom_property', 'utm', 'session_screen_with_property', 'session_screen_with_property_list', 'user_first_utm'].indexOf(segmentCopy[i].attribute) > -1
      object = JSON.stringify({
        o: segmentCopy[i].operator,
        en: segmentCopy[i].eventName,
        pn: isAppFilter ? segmentCopy[i].property_name : segmentCopy[i].propertyName,
        pt: segmentCopy[i].propertyType,
        pv: isAppFilter ? segmentCopy[i].value : segmentCopy[i].propertyValue,
        tb: segmentCopy[i].table,
        tzo: segmentCopy[i]?.timezoneOffset,
      })
      object = encodeURIComponent(object)
    }
    urlCopy = urlCopy.concat(sign, attribute, equalTo, object)
  }
  return urlCopy
}
export default urlSegmentEncoder
