import _ from 'underscore'
import Router from 'next/router'

import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder'
import {
  SCREEN_LIST,
  SCREEN_FLOW_DATA,
  CLEAR_SCREEN_BURST,
  SUN_BURST_DEPTH,
} from 'types'
import ScreenApi from 'services/screenApi'
import CommonApi from "services/commonApi"
import { maxDepthSunBurst } from 'components/features/navigation/constants'

import map from 'lodash/map';
import find from 'lodash/find';
import { getApiCalledTime, getErrorHandle, postErrorHandle } from './common'

export const gotScreenList = data => ({
    type: SCREEN_LIST,
    data
  })

export const gotScreenDetail = (data, type) => ({
    type: type || 'SCREEN_DETAIL',
    data
  })

export const clearSunBurst = () => ({
    type: CLEAR_SCREEN_BURST,
  })

export const getScreenList = () => (dispatch, getState) => ScreenApi.screenList(
    getState().currentAppReducer['_id'],
    getState().tokenReducer
  )
    .then(async res => {
      if (getState().urlReducer.parentType ===  'screensList') {
        dispatch(gotScreenList(res.data.data))
      }
      return res.data.data
    })
    .catch(error => getErrorHandle(dispatch, gotScreenList, error))

export const screenFlowLoader = flag => (dispatch, getState) => {
  const screenReducer = {
    ...getState().screenDetailReducer,
    screenFlwLoader: flag,
    keyVal: 'screenFlwLoader',
  };
  dispatch(gotScreenDetail(screenReducer, 'SCREEN_FLOW_DATA'))
}

export const sunBurstLoader = flag => (dispatch, getState) => {
  const screenReducer = {
    ...getState().screenDetailReducer,
    sunBurstLoader: flag,
    keyVal: 'sunBurstLoader',
  };
  dispatch(gotScreenDetail(screenReducer, 'SCREEN_FLOW_DATA'))
}

export const clearAllScreenFlowData = () => (dispatch, getState) => {
  let screenReducer = JSON.parse(JSON.stringify(getState().screenDetailReducer))
  screenReducer = _.omit(screenReducer, ['screenFlowPlotGraph'])
  dispatch(gotScreenDetail(screenReducer))
}

export const clearAllSunburstData = () => (dispatch, getState) => {
  let screenReducer = JSON.parse(JSON.stringify(getState().screenDetailReducer))
  screenReducer = _.omit(screenReducer, ['sunburst', 'sunburstPlotGraph'])
  dispatch(gotScreenDetail(screenReducer))
}

// Screen Flow actions
export const getScreenFlow =
  (payload, keyObject, isUserDetails, screenFlowImage = []) => async (dispatch, getState) => {
    const screenReducer = JSON.parse(
      JSON.stringify(getState().screenDetailReducer)
    );
    const { type: key } = keyObject;

    dispatch(screenFlowLoader(true));
    await dispatch(clearAllScreenFlowData());

    const { uxcamuserid, parentType, appId } = { ...getState().urlReducer };
    dispatch(getApiCalledTime(Math.floor(Date.now() / 1000)));
    let screenFlowSegment = JSON.parse( JSON.stringify(getState().appFilter.screenFlow.segment) );
    if (isUserDetails && uxcamuserid)
      screenFlowSegment = [
        ...screenFlowSegment,
        ...[
          {
            table: 'appuser',
            attribute: 'uxcamuserid',
            operator: 'in',
            value: [uxcamuserid],
          },
        ],
      ];
    const payloadCopy = { ...payload, filters: [...screenFlowSegment], };
    let url = `/app/${appId}/${parentType.toLowerCase()}?`;
    const query = `appId=${appId}&parentType=${parentType}`;
    url = urlSegmentEncoder(url, screenFlowSegment);
    !isUserDetails && Router.push(`/integration?${query}`, `${url}`);

    return CommonApi.pythonWithCancelApi(payloadCopy, 'screens/trino/sankey')
      .then(async (res) => {
        dispatch(getApiCalledTime());
        if (res.status === 200) {
          const data = await res.data.data;
          screenReducer[key] = data;
          screenReducer.keyVal = key;
          dispatch(screenFlowLoader(false));
          await dispatch(gotScreenDetail(screenReducer, 'SCREEN_FLOW_DATA'));
          return res.data;
        }
      })
      .then(async (res) => {
        const data = await res.data;
        const graphKeys = data?.series[0]?.keys;
        const indexOfFromScreen = _.indexOf(graphKeys, 'from_name');
        const indexOfToScreen = _.indexOf(graphKeys, 'to_name');
        const indexOfFromLink = _.indexOf(graphKeys, 'from_link');
        const indexOfToLink = _.indexOf(graphKeys, 'to_link');

        if(screenFlowImage.length > 0) {
          const newDataWithAddedImages = {
            ...data,
            series: [
                    {
                        ...data.series[0],
                        data: data.series[0].data.map((innerArr) => {
                            const updatedInnerArr = map(innerArr, (value, index) => {
                                if (index === indexOfFromScreen && find(screenFlowImage, { updatedScreenName: value })) {
                                    const matchingObj = find(screenFlowImage, { updatedScreenName: value });
                                    innerArr[indexOfFromLink] = matchingObj.screenShotImageUrl;
                                } else if (index === indexOfToScreen && find(screenFlowImage, { updatedScreenName: value })) {
                                    const matchingObj = find(screenFlowImage, { updatedScreenName: value });
                                    innerArr[indexOfToLink] = matchingObj.screenShotImageUrl;
                                }
                                return value;
                            });
                            return updatedInnerArr;
                            }
                        ),
                        nodes: data.series[0].nodes.map((item) => {
                                const matchingItem2 = _.find(screenFlowImage, { updatedScreenName: item.id });
                                if (matchingItem2) {
                                    return {
                                        ...item,
                                        link: matchingItem2.screenShotImageUrl
                                    };
                                }
                                return item;
                            }
                        )
                    }
                ]
            }
          const newScreenReducer = {
            ...screenReducer,
            ...newDataWithAddedImages,
            screenFlowPlotGraph: newDataWithAddedImages,
          }
          dispatch(gotScreenDetail(newScreenReducer, 'SCREEN_FLOW_DATA'));
        }
      })
      .catch(async (error) => {
        if (error && !error.toString().includes('Cancel')) {
          dispatch(getApiCalledTime());
          dispatch(screenFlowLoader(false));
          screenReducer.keyVal = key;
          screenReducer[key] = 'error';
          await dispatch(gotScreenDetail(screenReducer, 'SCREEN_FLOW_DATA'));
        }
        if(error?.response) postErrorHandle(dispatch, null, error.response);
      });
  };

export const getScreenBurst = (payload, keyObject, isUserDetails) => async (dispatch, getState) => {
  const screenReducer = JSON.parse(JSON.stringify(getState().screenDetailReducer))
  const { uxcamuserid, parentType, appId } = { ...getState().urlReducer }
  let screenFlowSegment = JSON.parse(JSON.stringify(getState().appFilter.screenFlow.segment))

  const { type: key } = keyObject;
  dispatch(sunBurstLoader(true))
  await dispatch(clearAllSunburstData())
  dispatch(getApiCalledTime(Math.floor(Date.now() / 1000)))
  if(isUserDetails && uxcamuserid)
    screenFlowSegment = [
      ...screenFlowSegment,
      ...[
        {
          table: 'appuser',
          attribute: 'uxcamuserid',
          operator: 'in',
          value: [uxcamuserid],
        },
      ],
    ];
  const payloadCopy = {
    ...payload,
    filters: [...screenFlowSegment],
    depth: payload.depth > maxDepthSunBurst  ? maxDepthSunBurst : screenReducer.sunBurstDepth
  };
  if (!isUserDetails) {
    let url = `/app/${appId}/${parentType.toLowerCase()}?`;
    const query = `appId=${appId}&parentType=${parentType}`;
    url = urlSegmentEncoder(url, screenFlowSegment);
    Router.push(`/integration?${query}`, `${url}`);
  }
  return CommonApi.sunBurstCancelApi(payloadCopy, 'screens/trino/sunburst')
    .then(async (res) => {
      dispatch(getApiCalledTime());
      if (res.status === 200) {
        const data = await res.data.data;
        screenReducer.sunburstPlotGraph = data;
        screenReducer.keyVal = 'sunburstPlotGraph';
        await dispatch(gotScreenDetail(screenReducer, SCREEN_FLOW_DATA));
        dispatch(sunBurstLoader(false));
        return res.data;
      }
    })
    .catch(async (error) => {
      dispatch(getApiCalledTime());
      if (error && !error.toString().includes('Cancel')) {
        screenReducer.keyVal = key;
        screenReducer[key] = error?.response?.data || {};
        await dispatch(gotScreenDetail(screenReducer, SCREEN_FLOW_DATA));
        dispatch(sunBurstLoader(false));
        if(error.response) postErrorHandle(dispatch, null, error.response);
      }
    });
}

