export const deleteUsersAndSessions = (data, type) => async (
  dispatch,
  getState
) => {
  const urlReducer = { ...getState().urlReducer }
  return UserApi.deleteUsersAndSessions(urlReducer.appId, data, type)
    .then((res) => res.data)
    // eslint-disable-next-line consistent-return
    .catch((error) => {
      if (error && error.response) {
        postErrorHandle(dispatch, undefined, error.response)
        return error.response
      }
    })
}

export const getUserDetail = (userId) => async (
  dispatch,
  getState
) => {
  dispatch(setError({}))
  dispatch(changeUserDetailVisibility(true))

  const requestPayload = {
    appid: getState().currentAppReducer['_id'],
    uxcamuserid: userId,
    date_range: getState().appFilter.dateSegment,
    filters: [],
  }
  return UserApi.userDetail(requestPayload)
    .then(async (res) => {
      if (
        getState().urlReducer.parentType === 'usersList' &&
        getState().urlReducer.uxcamuserid
      ) {
        await dispatch(gotUserDetail(res.data.data))
        dispatch(changeUserDetailVisibility(false))
      }
      return res.data.data
    })
    .catch((error) => {
      if (error && error.response) {
        dispatch(gotUserDetail(error.response))
      }
      getErrorHandle(dispatch, gotUserDetail, error)
      return error
    })
}

export const anyKeyData = (key, value) => (dispatch, getState) => {
  const userDetailReducer = { ...getState().userDetailReducer }
  userDetailReducer[key] = value
  dispatch(gotUserDetail(userDetailReducer))
}
export const getUserJourneyBoxes = (payload) => async (dispatch) => {
  dispatch(userJourneyBoxesLoader(true))
  return commonApi
    .forwardApi(payload, 'users/user_journey_boxes')
    .then(async (res) => {
      const data = await res.data
      dispatch(userJourneyBoxes(data))
      dispatch(userJourneyBoxesLoader(false))
      return res.data
    })
    .catch((error) => {
      dispatch(userJourneyBoxesLoader(false))
      if (error && error.response)
        postErrorHandle(dispatch, gotUserDetail, error.response)
      return error.response
    })
}
export const getUserJourneyGraph = (payload) => async (dispatch, getState) => {
  dispatch(userJourneyGraphLoader(true))
  const userDetailReducer = { ...getState().userDetailReducer }
  userDetailReducer.userJourneyGraphData &&
    (await dispatch(userJourneyGraph(undefined)))
  dispatch(getApiCalledTime(Math.floor(Date.now() / 1000)))
  return commonApi
    .pythonWithCancelApi(payload, 'users/user_journey_graph')
    .then(async (res) => {
      dispatch(getApiCalledTime())
      const data = await res.data
      dispatch(userJourneyGraph(data))
      dispatch(userJourneyGraphLoader(false))
      return res.data
    })
    .catch((error) => {
      if(error && !error.toString().includes('Cancel')){
        dispatch(getApiCalledTime())
        dispatch(userJourneyGraphLoader(false))
      }
      if (error && error.response)
        postErrorHandle(dispatch, gotUserDetail, error.response)
      return error.response
    })
}
