export const getLocationData = () => async (dispatch, getState) => {
  const { appId, uxcamuserid } = { ...getState().urlReducer };
  const { dateSegment } = { ...getState().appFilter }
  const payload = {
    appid: appId,
    uxcamuserid,
    filters: [dateSegment]
  }
  return UserApi.locationApi(payload)
    .then(async (res) => {
      let data = await res.data
      if (res.status === 200) {
        data = data.data
        dispatch(locationData(data))
        return data
      }
      return data
    })
    .catch((error) => {
      if (error && error.response)
        postErrorHandle(dispatch, null, error.response)
      return error
    })
}
