export const build_user_graph =  () => async (dispatch, getState) => {
  const urlReducer = { ...getState().urlReducer }
  const userAnalyticsReducer = { ...getState().userAnalyticsReducer }
  const { aggregation_list, group_list, series_plot_options, selectedBoxFilter } =
    userAnalyticsReducer
  const appFilter = { ...getState().appFilter }
  const filters = appFilter['user']['segment']
  const dateRange = appFilter?.usersList?.dateRange;
  const mergedFilter = [...filters, ...selectedBoxFilter, ...[ { ...appFilter.dateSegment } ]]
  const payload = {
    appid: urlReducer.appId,
    filters: mergedFilter,
    aggregation_list,
    group_list,
    dateRange,
    series_plot_options: omit(series_plot_options, 'display', 'key', 'img'),
  }
  await dispatch(userAnalyticsGraph())
  dispatch(graphLoader(true))
  return commonApi.pythonWithCancelApi(payload, 'users/build_user_graph')
    .then((response) => {
      const data = {
        data: {
          plot: response.data.data,
        },
        success: true
      }
      // const __r = response.data.data
      // __r.success = true
      dispatch(graphLoader(false))
      dispatch(userAnalyticsGraph(data))
    })
    .catch((error) => {
      dispatch(graphLoader(false))
      getErrorHandle(dispatch, userAnalyticsGraph, error)
    })
}
const getPayload = (prevDateRange,flag) => (...[,getState]) => {
  const appFilter = JSON.parse(JSON.stringify(getState().appFilter));
  const dateSegment = { ...getState().appFilter.dateSegment };
  const { appId: appid, parentType } = { ...getState().urlReducer };
  const isUserV2 = flag && parentType === 'usersList';
  const filters = getFilterListWithActivityFilterCheck(
    appFilter['user']['activityFilterList'],
    appFilter['user']['segment'],
    isUserV2,
  )

  const dateRangeIndex = filters.map(v => v.attribute).indexOf('date_range')
  if (dateRangeIndex > -1 && prevDateRange) filters[dateRangeIndex]['value'] = prevDateRange
  dateSegment['value'] = prevDateRange || dateSegment['value'];
  const payload =  {
    appid,
    filters,
    date_range: dateSegment
  }
  // * CX-1876: no need of dateRange for activity filter 
  isUserV2 && delete payload.date_range;
  return payload
}
export const get_users_statistics =  (prevDateRange, flag) => (dispatch) => {
  const payload = dispatch(getPayload(prevDateRange, flag))
  return UserApi.users_statistics(payload, flag)
    .then((response) => prevDateRange ? dispatch(userAnalyticsBoxesPrev(response?.data?.data)) : dispatch(userAnalyticsBoxes(response?.data?.data)))
    .catch((error) => getErrorHandle(dispatch, null, error));
}
