export const callUserAnalyticsBoxes = (anotherCall, userApiVersionFlag) => (dispatch, getState) => {
  let prevDateRange = ''
  if (anotherCall) {
    let prevDate;
    const dateSegment = { ...getState().appFilter.dateSegment }
    if (dateSegment) {
      const { value: { lower, upper }, label } = dateSegment;
    const getDateSubtracted = (num, period) => moment(lower).utc().subtract(num, period).format()
      switch (label) {
        case '1month':
          prevDate = getDateSubtracted(1, 'months');
          break;
        case '3months':
          prevDate = getDateSubtracted(3, 'months');
          break;
        case '14days':
          prevDate = getDateSubtracted(14, 'days');
          break;
        case '7days':
          prevDate = getDateSubtracted(7, 'days');
          break;
        case 'thisWeek':
          prevDate = getDateSubtracted(1, 'weeks');
          break;
        case 'yesterday':
          prevDate = getDateSubtracted(2, 'days');
          break;
        case 'today':
          prevDate = getDateSubtracted(1, 'days');
          break;
        case 'custom':
        case 'thisMonth':
          prevDate = moment.unix((Math.round(new Date(lower).getTime()) - moment(upper).diff(lower)) / 1000);
          prevDate = moment(prevDate).utc().format();
          break;
        default:
          break;
      }
      prevDateRange = {
        lower: (
          moment.unix(
            (Math.round(new Date(lower).getTime()) - moment(upper).diff(lower)) /
              1000
          ).utc().format()
        ),
        upper: (moment(lower).utc().format())
      }
    }
  }
  dispatch(callCardStatistics(prevDateRange, userApiVersionFlag))
}
export const resetUserAnalyticsData = () => dispatch => dispatch(resetAllStates())
export const setUserSelectedBox = (data) => dispatch => dispatch(setSelectedBox(data))
export const resetAllUserAnalyticsBox = () => dispatch => dispatch(resetAllBox())
export const callUserAnalyticsApis = (userApiVersionFlag) => async (dispatch) => {
  await dispatch(resetAllUserAnalyticsBox())
  dispatch(callUserAnalyticsBoxes(false, userApiVersionFlag || false))
  dispatch(callUserAnalyticsBoxes(true, userApiVersionFlag || false))
}
