export const attributeProperties = data => ({
  type: GET_ATTRIBUTE_PROPERTIES,
  data
})
export const getFilterPropertyRemoteData =
  (data, isFilterData, notCancelFilter, isWebApp) =>
  async (dispatch, getState) => {
    const { appId, app } = { ...getState().urlReducer };
    const { fetchProperty, dateSegment } = { ...getState().appFilter };
    const payloadCopy = { ...data };
    const { attribute, isWebApp: payloadWeb } = data;
    const isWebAppFlag = isWebApp || payloadWeb;
    let responseData;
    // Note: app is the default value for appId in case of settings page
    payloadCopy.appid = payloadCopy.appid || appId || app;
    payloadCopy.table = 'session';
    if (['viewid', 'viewname', 'viewtype'].includes(attribute)) {
      payloadCopy.table = 'gesture';
    }
    if(['session_screen_with_property'].includes(attribute)) {
      payloadCopy.table = 'screenvisit';
    }
    if (
      ['event_custom_property', 'event_name', 'event_activity_name'].indexOf(
        attribute
      ) > -1
    )
      payloadCopy.table = 'event';
      if (
        ['nce_name'].indexOf(
          attribute
        ) > -1
      )
        payloadCopy.table = 'no_code_event_rule';

    if(['user_device_country','user_device_city','user_device_platform','user_device_class',
        'user_device_manufacturer','user_device_os_version','user_device_model','user_app_version',
        'user_device_id'
    ].includes(attribute)){
        payloadCopy.table = 'appuser';
    }
    const apiName = notCancelFilter
      ? 'getPropertiesWithoutCancelToken'
      : 'getPropertiesWithCancelToken';
    const isEventProperty = attribute === 'event_custom_property';
    const isUtm = attribute === 'utm';
    const isFirstUtm = attribute === 'user_first_utm';
    const isCustomScreenProperty = attribute === 'session_screen_with_property';
    const isScreenProperty = attribute === 'session_screen_with_property_list';
    
    if (isCustomScreenProperty){
      payloadCopy.table = 'screenvisit'
    }

    if (!payloadCopy.date_range) {
      payloadCopy.date_range = dateSegment;
    }
    if(payloadCopy.attribute === 'session_screen_ordered_list') payloadCopy.attribute = 'screen_name' // WA-260 was session_screen_list before

    // Add mass value keys if they exist in the data
    if (data.has_mass_value !== undefined) {
      payloadCopy.has_mass_value = data.has_mass_value;
    }
    if (data.mass_value_segment_id) {
      payloadCopy.mass_value_segment_id = data.mass_value_segment_id;
    }
    if (data.mass_values_id) {
      payloadCopy.mass_values_id = data.mass_values_id;
    }

    try {
      const res = await FilterApi[apiName](payloadCopy);
      if (attribute) {
        let reduxAttribute = attribute
        if (payloadCopy.property_name) {
          const suffix = isFilterData ? 'ofgrp' : ''
          if (isEventProperty)
            reduxAttribute = `eventpropertyvalue${suffix}`
          if (isUtm)
            reduxAttribute = `utmpropertyvalue${suffix}`
          if (isFirstUtm)
            reduxAttribute = `userfirstutmvalue${suffix}`
          if (isScreenProperty)
            reduxAttribute = `sessionscreenpropertyvalue${suffix}`
          if (isCustomScreenProperty)
            reduxAttribute = `customscreenpropertyvalue${suffix}`
          else
            reduxAttribute = `userpropertyvalue${suffix}`
        }
        responseData = { data: res.data.data, attribute: reduxAttribute }
        // @NOTE - Commented out the grouping property retaining logic because of CX-1657
        // if (fetchProperty[reduxAttribute]?.data?.length) {
          if (reduxAttribute === 'uxcamuserid') {
            responseData['data'] = uniqBy(
              [...res.data.data
                // , ...fetchProperty[reduxAttribute]?.data
              ],
              'uxcamuserid'
            )
          } else if (reduxAttribute === 'nce_name') {
            responseData['data'] = uniqBy([
              ...res.data.data,
            ])
          }
          else
            responseData['data'] = uniqBy([
              ...res.data.data,
              // ...fetchProperty[reduxAttribute]?.data,
            ])
        // }
      }
      dispatch(attributeProperties(responseData))
      return res.data.data
    } catch (error) {
      return error && error.response
    }
  };

export const getSearchAttrRemoteData = (data) => async (_01, getState) => {
  const payloadCopy = { ...data };
  payloadCopy.table =
    ['event_custom_property', 'event_name', 'event_activity_name'].indexOf(
      payloadCopy.attribute
    ) > -1
      ? 'event'
      : 'session';
  payloadCopy.appid = getState().urlReducer.appId;
  return FilterApi.getPropertiesWithoutCancelToken(payloadCopy)
    .then((res) => res.data.data)
    .catch(() => []);

}

export const addSegmentV2 =
  (data = [], pageType) =>
  (dispatch, getState) => {
    const { parentType } = getState().urlReducer;
    const type = pageType || pageFilterMap[parentType];
    if(!type) return
    let page = type.split('-')[0];
    if (parentType === 'issues') page = 'issue';
    else if (parentType === 'screenBurst' || parentType === 'screenFlow') page = 'screenFlow';
    dispatch(
      addFilterSegment({
        page,
        data,
      })
    );
  };

 
export const addActivitySegment =
  (data = [], pageType) =>
  (dispatch, getState) => {
    const { parentType } = getState().urlReducer;
    const type = pageType || pageFilterMap[parentType];
    if(!type) return
    const page = type.split('-')[0];

    dispatch(
    addActivityFilterSegment({
        page,
        data,
      })
    );
  };

  
