export const deleteCustomLabelFilterFetchProperty = () => (dispatch, getState) => {
  const appFilter = { ...getState().appFilter }
  appFilter.fetchProperty.custom_label = undefined
  appFilter.fetchProperty.user_custom_label = undefined
  dispatch(uxcamFilter(appFilter))
}

export const clearAllFilter = () => (dispatch, getState) => {
  const appFilter = { ...getState().appFilter }
  const urlQ = { ...getState().urlReducer }
  if (
    [ 'sessionsList', 'sessionStatistics', 'aiSessionsList', 'aiSessionStatistics' ].includes( urlQ.parentType )
  ) {
    appFilter.session.segment = []
  } else if (urlQ.parentType === 'usersList') {
    appFilter.user.segment = []
  } else if (urlQ.parentType === 'screensList') {
    appFilter.screen.segment = []
  } else {
    appFilter.event.segment = []
  }
  dispatch(uxcamFilter(appFilter))
}

export const addIssuePageSegment = (data) => (dispatch, getState) => {
  const appFilter = JSON.parse(JSON.stringify(getState().appFilter))
    appFilter.issue.issuePageSegment = (typeof data === 'undefined') ? [] : [...data]
  dispatch(uxcamFilter(appFilter))
}

export const applySessionCustomFilter = (pageNumber) => async (_, getState) => {
    const {appId, parentType, sessionid: sessionId} = getState().urlReducer
    const isSession = sessionId ? `/${sessionId}` : ''
    let url = ''
    let query = ''
    let segment = []
    segment = [...getState().appFilter.session.segment ]
    url = `/app/${appId}/aisessions/list/${pageNumber || 1}${isSession}?`
    if (isSession) {
        url += `secondarysessionid=${sessionId}&`
    }
    url = urlSegmentEncoder(url, segment)
    query = sessionId
        ? `/integration?parentType=aiSessionsList&appId=${appId}&sessionpage=${pageNumber || 1}&sessionid=${sessionId}&secondarysessionid=${sessionId}`
        : `/integration?parentType=aiSessionsList&appId=${appId}&sessionpage=${pageNumber || 1}`
    parentType !== 'aiSessionStatistics' && Router.push(query, url)
}

export const applyAiSessionsPageApi = async ({ appId, sessionid, sessionpage, starttime }, segmentProps) => {
  let url;
  let query;
  
  if (sessionid) {
    if (starttime) {
      url = `/app/${appId}/aisessions/list/${sessionpage || 1}/${sessionid}/${starttime}?`;
      query = `appId=${appId}&parentType=aiSessionsList&sessionid=${sessionid}&sessionpage=${
        sessionpage || 1
      }&starttime=${starttime}`;
    } else {
      url = `/app/${appId}/aisessions/list/${sessionpage || 1}/${sessionid}?`;
      query = `appId=${appId}&parentType=aiSessionsList&sessionid=${sessionid}&sessionpage=${
        sessionpage || 1
      }`;
    }
  } else {
    url = `/app/${appId}/aisessions/list/${sessionpage || 1}?`;
    query = `appId=${appId}&parentType=aiSessionsList&sessionpage=${sessionpage || 1}`;
  }

  url = urlSegmentEncoder(url, segmentProps ? [...segmentProps] : []);
  Router.push(`/integration?${query}`, `${url}`);
};

export const applyIssuesCustomFilter = (pageNumber) => async (_, getState) => {
  const {
    appId,
    sessionid,
    issueType,
    issuepage: issuePage,
    issueid: issueId,
    starttime: timeOfIncidence,
  } = getState().urlReducer;
  let url = '';
  let query = '';
  let segment = [];
  segment = [...getState().appFilter.issue.segment];
  url = `/app/${appId}/issues/${issueType}/${issuePage || 1}/${issueId}/${
    issuePage || 1
  }/session/${sessionid}/${timeOfIncidence}?`;
  query = `/integration?parentType=issues&appId=${appId}&issueid=${issueId}&issueType=${issueType}&issuepage=${
    issuePage || 1
  }&issuedetailpage=${
    pageNumber || 1
  }&sessionid=${sessionid}&starttime=${timeOfIncidence}`;
  url = urlSegmentEncoder(url, segment);
  Router.push(query, url);
}
export const applyUserCustomFilter = (pageNumber, type, userApiVersionFlag, triggerAPI=true) => async (dispatch, getState) => {
    const filters = [...getState().appFilter.user.segment ];
    const activityFilters = type === 'user' &&  getState().appFilter.user?.activityFilterList ? [...getState().appFilter.user.activityFilterList ] : [];
    const isActivityFilterApplicable = type === 'user' && hasActivityFilterChangedFromDefaultState(activityFilters)
    const isUserV2 = userApiVersionFlag && type === 'user'; 
    let url = '';
    let query = '';
    const page = pageNumber || 1
    const { uxcamuserid:userId, appId:appid, parentType, sessionid, sessionpage, video } = getState().urlReducer
    if (parentType === 'usersList') {
      const uxcamuserid = userId ? `/${userId}` : ''
      const uxcamsessionid = sessionid
        ? `/sessions/list/${page}/${sessionid}`
        : ''
        url = `/app/${appid}/users/list/${page}${uxcamuserid}${uxcamsessionid}?`
        url = urlSegmentEncoder(url, filters)
        // * CX-1876 : APPENDING ACTIVITY SEGMENT AND CONFIG IF AVAILABLE
        if (isActivityFilterApplicable) {
            let params = '';
            if (activityFilters?.length) {
                params = aggregateByAttributeAndEncode(activityFilters);
            }
            url = `${url}&${params.toString()}`
        }
      query = `/integration?parentType=usersList&appId=${appid}&type=${
        getState().urlReducer.type
      }&userpage=${page}${
        userId ? `&uxcamuserid=${userId}`: ''
      }${sessionid
          ? `&sessionid=${sessionid}`
          : ''
      }${sessionpage
          ? `&sessionpage=${sessionpage}`
          : '&sessionpage=1'
      }${video
          ? `&video=${video}`
          : ''
      }`
    }
    // if(isUserV2){
    //   //* check for activityFilterList validity:
    //   const isValid = isValidActivityFilterSegment(activityFilters);
    //   if(isValid && triggerAPI){
    //     dispatch(callUserAnalyticsApis(userApiVersionFlag))
    //   }
    // }else{
    //     triggerAPI && dispatch(callUserAnalyticsApis(userApiVersionFlag));
    // }
    !isUserV2 && triggerAPI && dispatch(callUserAnalyticsApis(userApiVersionFlag))
    
    Router.push(query, url)
   
  }
export const resetFetchedPropertyByKey = (attribute) => (dispatch) => dispatch(attributeProperties({ data: [], attribute }));
export const setEventPropertyList = (eventPropertyList) => ({
  type: GET_EVENT_PROPERTY_LIST,
  eventPropertyList,
});
export const fetchEventPropertyList = () => async (dispatch, getState) => {
  try {
    const response = await FilterApi.getEventPropertyList(
      getState().urlReducer.appId
    );
    dispatch(setEventPropertyList(response.data.data))
  } catch (error) {
    getErrorHandle(dispatch, setEventPropertyList, error)
  }
};

