import _ from 'underscore'

export const loadSelectedEventCount = (
  selectedEventName,
  eventNameList,
  filter = [],
) => {
  if (
    selectedEventName.length &&
    selectedEventName.length !== eventNameList.length &&
    filter.length
  ) {
    const unSelectedEvent = eventNameList.filter((x) => {
      const eventIndex = _.indexOf(selectedEventName, x.eventname)
      if (eventIndex < 0) {
        return x
      }
    })

    let eventNameListValue = []
    let eventOperator = 'in'
    if (selectedEventName.length > unSelectedEvent.length) {
      if (unSelectedEvent.length === 0) {
        eventNameListValue = selectedEventName
        eventOperator = 'in'
      } else {
        eventNameListValue = unSelectedEvent.map((x) => x.eventname)
        eventOperator = 'notin'
      }
    } else if (selectedEventName.length < unSelectedEvent.length) {
      eventNameListValue = selectedEventName
      eventOperator = 'in'
    } else if (
      selectedEventName.length &&
      selectedEventName.length === unSelectedEvent.length
    ) {
      eventNameListValue = selectedEventName
      eventOperator = 'in'
    }
    const eventNameFilter = {
      table: 'event',
      attribute: 'event_name',
      operator: 'in' || eventOperator,
      value: selectedEventName || eventNameListValue || [],
    }
    const eventNameIndex = _.findIndex(filter, { attribute: 'event_name' })
    if (eventNameIndex >= 0) {
      filter[eventNameIndex] = eventNameFilter
    } else {
      filter.push(eventNameFilter)
    }
    return filter
  }
  return filter
}
export default loadSelectedEventCount
