/* eslint-disable no-plusplus */
import axios from 'axios';
import { axiosInstance } from './globalInstance';

const { CancelToken } = axios;
let cancel = null;
let request = 0;

let eventListTableCancel = null;
let eventListTableRequest = 0;
let nocodeEventListTableCancel = null;
let nocodeEventListTableRequest = 0;

class EventApi {
  static async getEventTable(data, appId) {
    request++;
    if (cancel) {
      await cancel(request);
    }
    // `${process.env.API_URL}/app/${appId}/event/event-count-list`,
    const res = await axiosInstance.post(
      `${process.env.PYTHON_API_URL_V2}/events/event_count`,
      data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a cancel function as a parameter
          cancel = c;
          request = 0;
        }),
      }
    );
    cancel = null;
    return res.data;
  }

  static async getV2EventListTable(data) {
    eventListTableRequest++;
    if (eventListTableCancel) await eventListTableCancel(eventListTableRequest);
    const res = await axiosInstance.post(
      `${process.env.PYTHON_API_URL_V2}/events/list`,
      data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a eventListTableCancel function as a parameter
          eventListTableCancel = c;
          eventListTableRequest = 0;
        }),
      }
    );
    eventListTableCancel = null;
    return res;
  }

  static async getV2NocodeEventListTable(data) {
    nocodeEventListTableRequest++;
    if (nocodeEventListTableCancel) await eventListTableCancel(nocodeEventListTableRequest);
    const res = await axiosInstance.post(
      `${process.env.PYTHON_API_URL}/no_code_event/list`,
      data,
      {
        withCredentials: true,
        cancelToken: new CancelToken((c) => {
          // An executor function receives a eventListTableCancel function as a parameter
          nocodeEventListTableCancel = c;
          nocodeEventListTableRequest = 0;
        }),
      }
    );
    nocodeEventListTableCancel = null;
    return res;
  }
}

export default EventApi;
